   182|
   183|const DEFAULT_PROJECT_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
   184|
   185|/** Resolve the project root for this run (injectable for tests). */
   186|function resolveProjectRoot(input: IVXAutonomousCoderInput): string {
