   190|// ── FILE INSPECTION ──────────────────────────────────────────────────────────
   191|
   192|const INSPECT_IGNORED_DIRS = new Set([
   193|  '.git', '.rork', 'node_modules', '.expo', 'dist', 'build', 'coverage',
   194|  'logs', 'tmp', '__tests__', '__mocks__', 'mocks', '.github',
   195|]);
   196|
   197|const INSPECTABLE_EXTENSIONS = new Set([
   198|  '.ts', '.tsx', '.js', '.jsx', '.mjs', '.json', '.md', '.yaml', '.yml',
   199|]);
   200|
   201|async function walkInspectableFiles(relDir: string, results: string[], max: number, projectRoot: string): Promise<void> {
   202|  if (results.length >= max) return;
   203|  const absDir = path.join(projectRoot, relDir);
   204|  let entries: string[];
   205|  try {
   206|    entries = await readdir(absDir);
   207|  } catch {
   208|    return;
   209|  }
   210|  for (const entry of entries) {
   211|    if (results.length >= max) return;
   212|    const relEntry = relDir ? `${relDir}/${entry}` : entry;
   213|    const absEntry = path.join(absDir, entry);
   214|    let info;
   215|    try {
   216|      info = await stat(absEntry);
   217|    } catch {
   218|      continue;
   219|    }
   220|    if (info.isDirectory()) {
   221|      if (INSPECT_IGNORED_DIRS.has(entry)) continue;
   222|      if (!relDir && entry !== 'backend' && entry !== 'expo') continue;
   223|      await walkInspectableFiles(relEntry, results, max, projectRoot);
   224|    } else if (info.isFile()) {
   225|      const ext = path.extname(entry);
   226|      if (INSPECTABLE_EXTENSIONS.has(ext)) {
   227|        results.push(relEntry);
   228|      }
   229|    }
   230|  }
   231|}
   232|
   233|function pickInspectionTargets(goal: string, availableFiles: string[]): string[] {
   234|  const alwaysInclude = [
   235|    'backend/services/ivx-autonomous-coder-pilot.ts',
   236|    'backend/services/ivx-senior-developer-worker.ts',
   237|    'backend/services/ivx-senior-developer-runtime.ts',
   238|    'backend/ivx-ai-runtime.ts',
   239|    'backend/api/ivx-owner-ai.ts',
   240|    'backend/hono.ts',
   241|    'render.yaml',
   242|    'package.json',
   243|  ].filter((f) => availableFiles.includes(f));
   244|
   245|  const words = Array.from(new Set(
   246|    goal.toLowerCase()
   247|      .replace(/[^a-z0-9\s]/g, ' ')
   248|      .split(/\s+/)
   249|      .filter((w) => w.length >= 4)
   250|      .filter((w) => !['that', 'this', 'with', 'from', 'have', 'please', 'change', 'deploy', 'anything', 'current', 'status', 'label', 'version'].includes(w)),
   251|  ));
   252|
   253|  const hintMatches = availableFiles
   254|    .filter((f) => words.some((w) => f.toLowerCase().includes(w)))
   255|    .slice(0, 15);
   256|
   257|  // Also include files whose CONTENT might contain the goal's significant terms.
   258|  // This is handled in the inspect phase by reading file previews.
   259|
   260|  return Array.from(new Set([...alwaysInclude, ...hintMatches])).slice(0, MAX_INSPECTED_FILES);
   261|}
   262|
   263|async function readFilePreview(relPath: string, projectRoot: string): Promise<{ path: string; content: string; bytes: number } | null> {
   264|  try {
   265|    const absPath = path.join(projectRoot, relPath);
   266|    const content = await readFile(absPath, 'utf8');
   267|    const bytes = Buffer.byteLength(content, 'utf8');
   268|    // Send full content for small files so the LLM can copy oldText verbatim.
   269|    const preview = bytes <= FULL_CONTENT_THRESHOLD ? content : truncate(content, FILE_PREVIEW_CHARS);
   270|    return { path: relPath, content: preview, bytes };
   271|  } catch {
   272|    return null;
   273|  }
   274|}
   275|
   276|// ── PATCH APPLICATION ────────────────────────────────────────────────────────
   277|
   278|/** Paths the autonomous coder is allowed to modify. */
   279|const ALLOWED_PATCH_PATHS = /^((?:backend|expo)\/[A-Za-z0-9_.\/-]+\.ts$|(?:backend|expo)\/[A-Za-z0-9_.\/-]+\.tsx$|expo\/[A-Za-z0-9_.\/-]+\.json$|expo\/[A-Za-z0-9_.\/-]+\.gradle$)/;
   280|
   281|function assertSafePatchPath(filePath: string): void {
   282|  if (filePath.includes('..') || filePath.startsWith('/')) {
   283|    throw new Error(`Unsafe patch path rejected: ${filePath}`);
   284|  }
   285|  if (!ALLOWED_PATCH_PATHS.test(filePath)) {
   286|    throw new Error(`Patch path outside allowed roots: ${filePath}. Only backend/*.ts, expo/*.ts(x), expo/*.json, expo/*.gradle are permitted.`);
   287|  }
   288|}
   289|
   290|async function applyPatchOperation(
   291|  op: IVXAutonomousCoderPatchOperation,
   292|  projectRoot: string,
   293|  fileWriter?: (relPath: string, content: string) => Promise<void>,
   294|  fileReader?: (relPath: string) => Promise<string>,
   295|): Promise<void> {
   296|  assertSafePatchPath(op.path);
   297|  const fullPath = path.join(projectRoot, op.path);
   298|  const write = fileWriter ?? (async (rel: string, content: string) => {
   299|    await mkdir(path.dirname(path.join(projectRoot, rel)), { recursive: true });
   300|    await writeFile(path.join(projectRoot, rel), content, 'utf8');
   301|  });
   302|  const read = fileReader ?? (async (rel: string) => readFile(path.join(projectRoot, rel), 'utf8'));
   303|  if (op.kind === 'create_file') {
   304|    const { existsSync } = await import('node:fs');
   305|    if (existsSync(fullPath)) {
   306|      throw new Error(`Create-file target already exists: ${op.path}`);
   307|    }
   308|    await write(op.path, op.newText);
   309|  } else {
   310|    const source = await read(op.path);
   311|    if (!source.includes(op.oldText)) {
   312|      throw new Error(`Patch oldText not found in ${op.path}; cannot apply safely.`);
   313|    }
   314|    const updated = source.replace(op.oldText, op.newText);
   315|    await write(op.path, updated);
   316|  }
   317|}
   318|
   319|async function revertPatchOperation(
   320|  op: IVXAutonomousCoderPatchOperation,
   321|  projectRoot: string,
   322|  fileWriter?: (relPath: string, content: string) => Promise<void>,
   323|  fileReader?: (relPath: string) => Promise<string>,
   324|): Promise<void> {
   325|  const write = fileWriter ?? (async (rel: string, content: string) => {
   326|    await mkdir(path.dirname(path.join(projectRoot, rel)), { recursive: true });
   327|    await writeFile(path.join(projectRoot, rel), content, 'utf8');
   328|  });
   329|  const read = fileReader ?? (async (rel: string) => readFile(path.join(projectRoot, rel), 'utf8'));
   330|  if (op.kind === 'create_file') {
   331|    try { await rm(path.join(projectRoot, op.path)); } catch { /* already gone */ }
   332|  } else {
   333|    try {
   334|      const source = await read(op.path);
   335|      if (source.includes(op.newText)) {
   336|        await write(op.path, source.replace(op.newText, op.oldText));
   337|      }
   338|    } catch { /* file may not exist */ }
   339|  }
   340|}
