   342|// ── TEST + TYPECHECK RUNNER ──────────────────────────────────────────────────
   343|
   344|async function runCommand(cwd: string, command: string): Promise<IVXAutonomousCoderTestResult> {
   345|  const started = Date.now();
   346|  // Resolve the runtime: the Render container runs under node+tsx, not bun.
   347|  // `bun test` and `bun x tsc` fail with ENOENT on the production container, so
   348|  // we resolve the runtime via resolveRuntimeCommand and translate the command
   349|  // to its node-based equivalent when bun is not available.
   350|  const parts = command.split(/\s+/);
   351|  const requestedRuntime = parts[0] as 'bun' | 'bunx' | 'node' | 'npx';
   352|  const resolution = resolveRuntimeCommand(requestedRuntime);
   353|  let effectiveCmd = resolution.resolvedPath ?? resolution.effectiveCommand;
   354|  let effectiveArgs = parts.slice(1);
   355|  let displayCommand = command;
   356|  // When bun falls back to node, translate `bun test <file>` → `node --test <file>`
   357|  // (node:test runner) and `bun x tsc --noEmit` → `npx tsc --noEmit` (or node tsc).
   358|  if (resolution.usedFallback && requestedRuntime === 'bun') {
   359|    if (effectiveArgs[0] === 'test') {
   360|      effectiveArgs = ['--test', ...effectiveArgs.slice(1)];
   361|      displayCommand = `node --test ${effectiveArgs.slice(1).join(' ')}`;
   362|    } else if (effectiveArgs[0] === 'x') {
   363|      // `bun x tsc` → use npx instead
   364|      const npxRes = resolveRuntimeCommand('npx');
   365|      effectiveCmd = npxRes.resolvedPath ?? npxRes.effectiveCommand;
   366|      effectiveArgs = effectiveArgs.slice(1); // drop the 'x'
   367|      displayCommand = `npx ${effectiveArgs.join(' ')}`;
   368|    }
   369|  }
   370|  try {
   371|    const result = await execFileAsync(effectiveCmd, effectiveArgs, {
   372|      cwd,
   373|      timeout: COMMAND_TIMEOUT_MS,
   374|      maxBuffer: 1024 * 1024 * 4,
   375|      env: { ...process.env, CI: '1', FORCE_COLOR: '0' },
   376|    });
   377|    return {
   378|      command: displayCommand,
   379|      ok: true,
   380|      exitCode: 0,
   381|      stdoutTail: truncate(typeof result.stdout === 'string' ? result.stdout : '', 2000),
   382|      stderrTail: truncate(typeof result.stderr === 'string' ? result.stderr : '', 2000),
   383|      durationMs: Date.now() - started,
   384|    };
   385|  } catch (error) {
   386|    const err = error as { code?: number; stdout?: string; stderr?: string; signal?: string };
   387|    return {
   388|      command: displayCommand,
   389|      ok: false,
   390|      exitCode: typeof err.code === 'number' ? err.code : null,
   391|      stdoutTail: truncate(typeof err.stdout === 'string' ? err.stdout : '', 2000),
   392|      stderrTail: truncate(typeof err.stderr === 'string' ? err.stderr : '', 2000),
   393|      durationMs: Date.now() - started,
   394|    };
   395|  }
   396|}
