   398|/** Pick the most relevant test file for the goal. */
   399|function pickTargetTestFile(goal: string, changedFiles: string[]): string {
   400|  // If a changed file has a corresponding .test.ts, run it.
   401|  for (const changed of changedFiles) {
   402|    const testFile = changed.replace(/\.ts$/, '.test.ts').replace(/^backend\//, 'backend/');
   403|    if (testFile !== changed) {
   404|      // Check if the test file path matches a known test pattern
   405|      return testFile;
   406|    }
   407|  }
   408|  // Default: run the autonomous coder's own tests
   409|  return 'backend/ivx-autonomous-coder.test.ts';
   410|}
   411|
   412|// ── LLM PATCH GENERATION ─────────────────────────────────────────────────────
   413|
   414|const PATCH_SYSTEM_PROMPT = `You are the IVX Autonomous Coder — a real senior developer engine.
   415|Given a GOAL and FILE CONTENTS, generate a JSON patch to achieve the goal.
   416|
   417|OUTPUT FORMAT (strict JSON, no markdown, no prose):
   418|{
   419|  "rootCause": "one-line root cause",
   420|  "technicalPlan": "one-line plan",
   421|  "operations": [
   422|    {
   423|      "path": "backend/services/example.ts",
   424|      "kind": "replace_exact",
   425|      "oldText": "the exact text to find",
   426|      "newText": "the replacement text",
   427|      "reason": "why this change"
   428|    }
   429|  ]
   430|}
   431|
   432|Rules:
   433|- kind must be "replace_exact" (replace oldText with newText) or "create_file" (new file).
   434|- oldText must be an EXACT substring of the file content (copy it verbatim).
   435|- Make the smallest safe change.
   436|- Only modify files under backend/ or expo/.
   437|- No secrets, no destructive operations.`;
   438|
   439|function buildPatchUserPrompt(goal: string, files: { path: string; content: string }[], failureContext: string | null): string {
   440|  const fileBlocks = files.map((f) => `--- FILE: ${f.path} ---\n${f.content}`).join('\n\n');
   441|  const failureBlock = failureContext
   442|    ? `\n\n--- PREVIOUS ATTEMPT FAILED ---\n${failureContext}\n\nRevise the patch to fix the failure. Output the corrected JSON.`
   443|    : '';
   444|  return `GOAL:\n${goal}\n\nFILES:\n${fileBlocks}${failureBlock}`;
   445|}
   446|
   447|function parseLLMPatchResponse(response: string): { rootCause: string; technicalPlan: string; operations: IVXAutonomousCoderPatchOperation[] } | null {
   448|  try {
   449|    // Strip markdown code fences if present
   450|    const cleaned = response.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
   451|    // Find the first { and last }
   452|    const start = cleaned.indexOf('{');
   453|    const end = cleaned.lastIndexOf('}');
   454|    if (start < 0 || end < 0 || end <= start) return null;
   455|    const jsonStr = cleaned.slice(start, end + 1);
   456|    const parsed = JSON.parse(jsonStr) as {
   457|      rootCause?: string;
   458|      technicalPlan?: string;
   459|      operations?: Array<{
   460|        path?: string;
   461|        kind?: string;
   462|        oldText?: string;
   463|        newText?: string;
   464|        reason?: string;
   465|      }>;
   466|    };
   467|    if (!Array.isArray(parsed.operations)) return null;
   468|    const operations: IVXAutonomousCoderPatchOperation[] = [];
   469|    for (const op of parsed.operations) {
   470|      if (typeof op.path !== 'string' || typeof op.kind !== 'string') continue;
   471|      if (op.kind !== 'replace_exact' && op.kind !== 'create_file') continue;
   472|      if (typeof op.oldText !== 'string' || typeof op.newText !== 'string') continue;
   473|      operations.push({
   474|        path: op.path,
   475|        kind: op.kind,
   476|        oldText: op.oldText,
   477|        newText: op.newText,
   478|        reason: typeof op.reason === 'string' ? op.reason : '',
   479|      });
   480|    }
   481|    if (operations.length === 0) return null;
   482|    return {
   483|      rootCause: typeof parsed.rootCause === 'string' ? parsed.rootCause : 'LLM-generated patch',
   484|      technicalPlan: typeof parsed.technicalPlan === 'string' ? parsed.technicalPlan : 'Replace exact text per operations',
   485|      operations,
   486|    };
   487|  } catch {
   488|    return null;
   489|  }
   490|}
   491|
   492|async function callLLMForPatch(
   493|  system: string,
   494|  user: string,
   495|  llmCaller?: (system: string, user: string) => Promise<string>,
   496|): Promise<string> {
   497|  if (llmCaller) return llmCaller(system, user);
   498|  const result = await requestIVXAIText({
   499|    module: 'ivx-autonomous-coder',
   500|    requestId: `ac-${randomUUID()}`,
   501|    system,
   502|    prompt: user,
   503|    maxOutputTokens: 4096,
   504|  });
   505|  return result.text;
   506|}
