   508|// ── GITHUB COMMIT (Git Data API) ─────────────────────────────────────────────
   509|
   510|const GITHUB_API_BASE_URL = 'https://api.github.com';
   511|const GITHUB_DEFAULT_BRANCH = 'main';
   512|
   513|function readEnv(name: string): string {
