   548|async function commitFilesViaGitDataApi(
   549|  filePaths: string[],
   550|  branch: string,
   551|): Promise<{ commitSha: string; commitUrl: string; branch: string }> {
   552|  const repoUrl = readEnv('GITHUB_REPO_URL');
   553|  const token = readEnv('GITHUB_TOKEN');
   554|  const repoInfo = parseGithubRepoUrl(repoUrl);
   555|  if (!repoInfo) throw new Error('GITHUB_REPO_URL is missing or invalid.');
   556|  if (!token) throw new Error('GITHUB_TOKEN is missing.');
   557|
   558|  const headers = {
   559|    Authorization: `Bearer ${token}`,
   560|    Accept: 'application/vnd.github+json',
   561|    'Content-Type': 'application/json',
   562|  };
   563|
   564|  // Read the branch ref
   565|  const refRes = await fetch(
   566|    `${GITHUB_API_BASE_URL}/repos/${repoInfo.owner}/${repoInfo.repo}/git/ref/heads/${encodeURIComponent(branch)}`,
   567|    { headers, signal: AbortSignal.timeout(10000) },
   568|  );
   569|  if (!refRes.ok) throw new Error(`GitHub branch ref lookup failed: ${refRes.status}`);
   570|  const refData = await refRes.json() as { object?: { sha?: string } };
   571|  const baseCommitSha = refData.object?.sha;
   572|  if (!baseCommitSha) throw new Error('GitHub branch ref did not include a commit SHA.');
   573|
   574|  // Get the base commit's tree
   575|  const commitRes = await fetch(
   576|    `${GITHUB_API_BASE_URL}/repos/${repoInfo.owner}/${repoInfo.repo}/git/commits/${encodeURIComponent(baseCommitSha)}`,
   577|    { headers, signal: AbortSignal.timeout(10000) },
   578|  );
   579|  if (!commitRes.ok) throw new Error(`GitHub base commit lookup failed: ${commitRes.status}`);
   580|  const commitData = await commitRes.json() as { tree?: { sha?: string } };
   581|  const baseTreeSha = commitData.tree?.sha;
   582|  if (!baseTreeSha) throw new Error('GitHub base commit did not include a tree SHA.');
   583|
   584|  // Create the new tree with the changed files
   585|  const tree = await Promise.all(filePaths.map(async (repoPath) => ({
   586|    path: repoPath,
   587|    mode: '100644' as const,
   588|    type: 'blob' as const,
   589|    content: await readFile(path.join(DEFAULT_PROJECT_ROOT, repoPath), 'utf8'),
   590|  })));
   591|
   592|  const treeRes = await fetch(
   593|    `${GITHUB_API_BASE_URL}/repos/${repoInfo.owner}/${repoInfo.repo}/git/trees`,
   594|    {
   595|      method: 'POST',
   596|      headers,
   597|      body: JSON.stringify({ base_tree: baseTreeSha, tree }),
   598|      signal: AbortSignal.timeout(15000),
   599|    },
   600|  );
   601|  if (!treeRes.ok) throw new Error(`GitHub tree creation failed: ${treeRes.status}`);
   602|  const treeData = await treeRes.json() as { sha?: string };
   603|  const newTreeSha = treeData.sha;
   604|  if (!newTreeSha) throw new Error('GitHub tree creation did not return a tree SHA.');
   605|
   606|  // Create the commit
   607|  const newCommitRes = await fetch(
   608|    `${GITHUB_API_BASE_URL}/repos/${repoInfo.owner}/${repoInfo.repo}/git/commits`,
   609|    {
   610|      method: 'POST',
   611|      headers,
   612|      body: JSON.stringify({
   613|        message: `IVX autonomous coder: ${new Date().toISOString()}`,
   614|        tree: newTreeSha,
   615|        parents: [baseCommitSha],
   616|      }),
   617|      signal: AbortSignal.timeout(15000),
   618|    },
   619|  );
   620|  if (!newCommitRes.ok) throw new Error(`GitHub commit creation failed: ${newCommitRes.status}`);
   621|  const newCommitData = await newCommitRes.json() as { sha?: string };
   622|  const commitSha = newCommitData.sha;
   623|  if (!commitSha) throw new Error('GitHub commit creation did not return a commit SHA.');
   624|
   625|  // Update the branch ref
   626|  const updateRes = await fetch(
   627|    `${GITHUB_API_BASE_URL}/repos/${repoInfo.owner}/${repoInfo.repo}/git/refs/heads/${encodeURIComponent(branch)}`,
   628|    {
   629|      method: 'PATCH',
   630|      headers,
   631|      body: JSON.stringify({ sha: commitSha, force: false }),
   632|      signal: AbortSignal.timeout(10000),
   633|    },
   634|  );
   635|  if (!updateRes.ok) throw new Error(`GitHub branch update failed: ${updateRes.status}`);
   636|
   637|  return {
   638|    commitSha,
   639|    commitUrl: `https://github.com/${repoInfo.owner}/${repoInfo.repo}/commit/${commitSha}`,
   640|    branch,
   641|  };
   642|}
