   646|async function triggerRenderDeploy(commitSha: string): Promise<{ deployId: string | null; deployStatus: string | null }> {
   647|  const apiKey = readEnv('RENDER_API_KEY');
   648|  const serviceId = readEnv('RENDER_SERVICE_ID');
   649|  if (!apiKey || !serviceId) {
   650|    throw new Error('RENDER_API_KEY or RENDER_SERVICE_ID is missing.');
