   664|    throw new Error(`Render deploy trigger failed: ${res.status} ${body.slice(0, 300)}`);
   665|  }
   666|  const data = await res.json() as { id?: string; status?: string };
   667|  return { deployId: data.id ?? null, deployStatus: data.status ?? 'triggered' };
