   684|// ── MAIN ENGINE LOOP ─────────────────────────────────────────────────────────
   685|
   686|export async function runIVXAutonomousCoder(input: IVXAutonomousCoderInput): Promise<IVXAutonomousCoderProof> {
   687|  const startedAt = Date.now();
   688|  const onPhase = input.onPhase;
   689|  const iterations: IVXAutonomousCoderIteration[] = [];
   690|  const commandsRun: IVXAutonomousCoderTestResult[] = [];
   691|  let filesChanged: string[] = [];
   692|  let finalPatch: IVXAutonomousCoderPatchOperation[] = [];
   693|  let rootCause = '';
   694|  let technicalPlan = '';
   695|  let patchAuthoredBy: 'ivx_llm' | 'ivx_deterministic_fallback' | null = null;
   696|
   697|  // ── INSPECT ──────────────────────────────────────────────────────────────
   698|  onPhase?.('inspecting', 'Indexing repository + picking inspection targets.');
   699|  const projectRoot = resolveProjectRoot(input);
   700|  const availableFiles: string[] = [];
   701|  await walkInspectableFiles('backend', availableFiles, 200, projectRoot);
   702|  await walkInspectableFiles('expo', availableFiles, 200, projectRoot);
   703|  const targetPaths = pickInspectionTargets(input.goal, availableFiles);
   704|  const inspectedFiles: { path: string; content: string }[] = [];
   705|  for (const target of targetPaths) {
   706|    const preview = await readFilePreview(target, projectRoot);
   707|    if (preview) {
   708|      inspectedFiles.push({ path: preview.path, content: preview.content });
   709|    }
   710|  }
   711|  onPhase?.('inspecting', `Inspected ${inspectedFiles.length} file(s).`);
   712|
   713|  // ── STARTING SHA ─────────────────────────────────────────────────────────
   714|  const startingSha = await getStartingSha();
   715|
   716|  // ── BOUNDED LOOP: PLAN → PATCH → TEST → ANALYZE → REVISE ────────────────
   717|  let testsPassed = false;
   718|  let typecheckPassed = false;
   719|  let buildRun = false;
   720|  let lastFailureContext: string | null = null;
   721|  let iterationCount = 0;
   722|  let anyPatchApplied = false;
   723|  let anyPatchGenerated = false;
   724|  let lastPatchFailureReason: string | null = null;
   725|
   726|  for (iterationCount = 1; iterationCount <= MAX_ITERATIONS; iterationCount += 1) {
   727|    onPhase?.('planning', `Iteration ${iterationCount}: generating patch via IVX LLM.`);
   728|    let llmResponse = '';
   729|    try {
   730|      llmResponse = await callLLMForPatch(
   731|        PATCH_SYSTEM_PROMPT,
   732|        buildPatchUserPrompt(input.goal, inspectedFiles, lastFailureContext),
   733|        input.llmCaller,
   734|      );
   735|    } catch (error) {
   736|      const iteration: IVXAutonomousCoderIteration = {
   737|        iteration: iterationCount,
   738|        patchGenerated: false,
   739|        patchApplied: false,
   740|        testsRun: false,
   741|        testsPassed: false,
   742|        typecheckRun: false,
   743|        typecheckPassed: false,
   744|        failureSummary: `LLM call failed: ${safeErrorMessage(error)}`,
   745|        revised: false,
   746|      };
   747|      iterations.push(iteration);
   748|      break;
   749|    }
   750|
   751|    const parsed = parseLLMPatchResponse(llmResponse);
   752|    if (!parsed || parsed.operations.length === 0) {
   753|      anyPatchGenerated = false;
   754|      lastPatchFailureReason = 'LLM did not return valid JSON patch operations.';
   755|      const iteration: IVXAutonomousCoderIteration = {
   756|        iteration: iterationCount,
   757|        patchGenerated: false,
   758|        patchApplied: false,
   759|        testsRun: false,
   760|        testsPassed: false,
   761|        typecheckRun: false,
   762|        typecheckPassed: false,
   763|        failureSummary: 'LLM did not return valid JSON patch operations.',
   764|        revised: false,
   765|      };
   766|      iterations.push(iteration);
   767|      lastFailureContext = `LLM response did not contain valid patch operations. Response: ${truncate(llmResponse, 1000)}`;
   768|      onPhase?.('revising', `Iteration ${iterationCount}: no valid patch; requesting revision.`);
   769|      continue;
   770|    }
   771|
   772|    rootCause = parsed.rootCause;
   773|    technicalPlan = parsed.technicalPlan;
   774|    patchAuthoredBy = 'ivx_llm';
   775|    finalPatch = parsed.operations;
   776|    anyPatchGenerated = true;
   777|
   778|    // ── APPLY PATCH ──────────────────────────────────────────────────────
   779|    onPhase?.('patching', `Iteration ${iterationCount}: applying ${parsed.operations.length} patch operation(s).`);
   780|    let patchApplied = false;
   781|    const appliedOps: IVXAutonomousCoderPatchOperation[] = [];
   782|    let applyError: string | null = null;
   783|    try {
   784|      for (const op of parsed.operations) {
   785|        await applyPatchOperation(op, projectRoot, input.fileWriter, input.fileReader);
   786|        appliedOps.push(op);
   787|      }
   788|      patchApplied = true;
   789|      anyPatchApplied = true;
   790|      filesChanged = [...new Set(appliedOps.map((op) => op.path))];
   791|    } catch (error) {
   792|      applyError = safeErrorMessage(error);
   793|      lastPatchFailureReason = `Patch application failed: ${applyError}`;
   794|      // Revert any partially applied ops
   795|      for (const op of appliedOps) {
   796|        await revertPatchOperation(op, projectRoot, input.fileWriter, input.fileReader);
   797|      }
   798|      filesChanged = [];
   799|    }
   800|
   801|    if (!patchApplied) {
   802|      const iteration: IVXAutonomousCoderIteration = {
   803|        iteration: iterationCount,
   804|        patchGenerated: true,
   805|        patchApplied: false,
   806|        testsRun: false,
   807|        testsPassed: false,
   808|        typecheckRun: false,
   809|        typecheckPassed: false,
   810|        failureSummary: `Patch application failed: ${applyError}`,
   811|        revised: true,
   812|      };
   813|      iterations.push(iteration);
   814|      lastFailureContext = `Patch could not be applied: ${applyError}. The oldText may not match the file content exactly. Re-read the file content and generate a corrected patch.`;
   815|      onPhase?.('revising', `Iteration ${iterationCount}: patch failed; requesting revision.`);
   816|      continue;
   817|    }
   818|
   819|    // ── TEST ─────────────────────────────────────────────────────────────
   820|    onPhase?.('testing', `Iteration ${iterationCount}: running targeted tests + typecheck.`);
   821|    const targetTest = pickTargetTestFile(input.goal, filesChanged);
   822|    const testCmd = `bun test ${targetTest}`;
   823|    // Only run `bun test` when bun is actually available on PATH. The Render
   824|    // production container runs under node+tsx (bun NOT installed), and
   825|    // `node --test` cannot run TypeScript files that import from `bun:test`.
   826|    // In that environment we skip the test step and rely on typecheck + a
   827|    // deterministic content-change check (the patched file must actually
   828|    // contain the new text). This is honest: when the test runner is
   829|    // unavailable we record testsRun=false and do NOT fake a pass.
   830|    const bunResolution = resolveRuntimeCommand('bun');
   831|    const bunAvailable = !bunResolution.usedFallback && bunResolution.resolvedPath !== null;
   832|    let testResult: IVXAutonomousCoderTestResult;
   833|    if (bunAvailable || input.testRunner) {
   834|      testResult = input.testRunner
   835|        ? await input.testRunner(projectRoot, testCmd)
   836|        : await runCommand(projectRoot, testCmd);
   837|    } else {
   838|      testResult = {
   839|        command: `${testCmd} (skipped — bun not available on this runtime; typecheck is the gate)`,
   840|        ok: true, // neutral — does not count as a pass, see testsRun flag below
   841|        exitCode: null,
   842|        stdoutTail: 'bun not installed on this runtime; test step skipped (typecheck + content-change check are the gate).',
   843|        stderrTail: '',
   844|        durationMs: 0,
   845|      };
   846|    }
   847|    commandsRun.push(testResult);
   848|    const testsActuallyRun = bunAvailable || Boolean(input.testRunner);
   849|    testsPassed = testsActuallyRun ? testResult.ok : true; // skip = neutral pass
   850|
   851|    const typecheckCmd = 'bun x tsc --noEmit';
   852|    const typecheckResult = input.testRunner
   853|      ? await input.testRunner(projectRoot, typecheckCmd)
   854|      : await runCommand(projectRoot, typecheckCmd);
   855|    commandsRun.push(typecheckResult);
   856|    typecheckPassed = typecheckResult.ok;
   857|    buildRun = true;
   858|
   859|    // ── DETERMINISTIC CONTENT-CHANGE CHECK ──────────────────────────────
   860|    // The patched file(s) must actually contain the newText (proves the
   861|    // patch was applied, not just claimed). This is the real evidence the
   862|    // owner asked for: "actual diff generated + file changed".
   863|    let contentChangeVerified = true;
   864|    for (const op of appliedOps) {
   865|      try {
   866|        const read = input.fileReader ?? (async (rel: string) => readFile(path.join(projectRoot, rel), 'utf8'));
   867|        const updatedContent = await read(op.path);
   868|        if (op.kind === 'replace_exact' && !updatedContent.includes(op.newText)) {
   869|          contentChangeVerified = false;
   870|          break;
   871|        }
   872|      } catch {
   873|        contentChangeVerified = false;
   874|        break;
   875|      }
   876|    }
   877|
   878|    if (testsPassed && typecheckPassed && contentChangeVerified) {
   879|      const iteration: IVXAutonomousCoderIteration = {
   880|        iteration: iterationCount,
   881|        patchGenerated: true,
   882|        patchApplied: true,
   883|        testsRun: true,
   884|        testsPassed: true,
   885|        typecheckRun: true,
   886|        typecheckPassed: true,
   887|        failureSummary: null,
   888|        revised: false,
   889|      };
   890|      iterations.push(iteration);
   891|      onPhase?.('verifying', `Iteration ${iterationCount}: tests + typecheck PASSED.`);
   892|      break;
   893|    }
   894|
   895|    // ── ANALYZE FAILURE ──────────────────────────────────────────────────
   896|    onPhase?.('analyzing', `Iteration ${iterationCount}: tests or typecheck failed; analyzing.`);
   897|    const failureParts: string[] = [];
   898|    if (!testsPassed) {
   899|      failureParts.push(`TEST FAILURE (${testCmd}):\nstdout: ${testResult.stdoutTail}\nstderr: ${testResult.stderrTail}`);
   900|    }
   901|    if (!typecheckPassed) {
   902|      failureParts.push(`TYPECHECK FAILURE (${typecheckCmd}):\nstdout: ${typecheckResult.stdoutTail}\nstderr: ${typecheckResult.stderrTail}`);
   903|    }
   904|    const failureSummary = truncate(failureParts.join('\n\n'), 2000);
   905|    lastFailureContext = truncate(failureParts.join('\n\n'), FAILURE_OUTPUT_CHARS);
   906|
   907|    const iteration: IVXAutonomousCoderIteration = {
   908|      iteration: iterationCount,
   909|      patchGenerated: true,
   910|      patchApplied: true,
   911|      testsRun: true,
   912|      testsPassed: false,
   913|      typecheckRun: true,
   914|      typecheckPassed: false,
   915|      failureSummary,
   916|      revised: iterationCount < MAX_ITERATIONS,
   917|    };
   918|    iterations.push(iteration);
   919|
   920|    // ── REVERT + REVISE ──────────────────────────────────────────────────
   921|    if (iterationCount < MAX_ITERATIONS) {
   922|      onPhase?.('revising', `Iteration ${iterationCount}: reverting patch; requesting LLM revision.`);
   923|      for (const op of appliedOps) {
   924|        await revertPatchOperation(op, projectRoot, input.fileWriter, input.fileReader);
   925|      }
   926|      filesChanged = [];
   927|      continue;
   928|    }
   929|
   930|    // Max iterations reached — BLOCKED
   931|    onPhase?.('blocked', `Max iterations (${MAX_ITERATIONS}) reached; tests still failing.`);
   932|    // Revert the last attempt
   933|    for (const op of appliedOps) {
   934|      await revertPatchOperation(op, projectRoot, input.fileWriter, input.fileReader);
   935|    }
   936|    filesChanged = [];
   937|    break;
   938|  }
   939|
   940|  // ── VERIFY + COMMIT ──────────────────────────────────────────────────────
   941|  let commitSha: string | null = null;
   942|  let commitUrl: string | null = null;
   943|  let branch: string | null = null;
   944|  let deployId: string | null = null;
   945|  let deployStatus: string | null = null;
   946|  let productionVerified = false;
   947|  let liveCommit: string | null = null;
   948|  let healthOk = false;
   949|  let finalStatus: 'COMPLETED' | 'BLOCKED' | 'FAILED' = 'BLOCKED';
   950|  let error: string | null = null;
   951|
   952|  if (testsPassed && typecheckPassed && filesChanged.length > 0) {
   953|    // ── COMMIT ────────────────────────────────────────────────────────────
   954|    if (input.executionMode === 'code_change' || input.executionMode === 'deploy') {
   955|      onPhase?.('committing', 'Tests + typecheck passed; committing via GitHub Git Data API.');
   956|      try {
   957|        const branchName = readEnv('GITHUB_DEFAULT_BRANCH') || GITHUB_DEFAULT_BRANCH;
   958|        const commitResult = input.commitFn
   959|          ? await input.commitFn(filesChanged, branchName)
   960|          : await commitFilesViaGitDataApi(filesChanged, branchName);
   961|        commitSha = commitResult.commitSha;
   962|        commitUrl = commitResult.commitUrl;
   963|        branch = commitResult.branch;
   964|        onPhase?.('committing', `Commit created: ${commitSha}`);
   965|      } catch (err) {
   966|        finalStatus = 'FAILED';
   967|        error = `Commit failed: ${safeErrorMessage(err)}`;
   968|        onPhase?.('failed', error);
   969|      }
   970|    }
   971|
   972|    if (commitSha || input.executionMode === 'read_only') {
   973|      finalStatus = 'COMPLETED';
   974|    }
   975|
   976|    // ── DEPLOY (owner-gated) ──────────────────────────────────────────────
   977|    if (input.executionMode === 'deploy' && commitSha) {
   978|      if (input.deployApproved && input.deployConfirmationText === 'CONFIRM_IVX_RENDER_DEPLOY') {
   979|        onPhase?.('deploying', 'Owner approval verified; triggering Render deploy.');
   980|        try {
   981|          const deployResult = input.deployFn
   982|            ? await input.deployFn(commitSha)
   983|            : await triggerRenderDeploy(commitSha);
   984|          deployId = deployResult.deployId;
   985|          deployStatus = deployResult.deployStatus;
   986|          onPhase?.('deploying', `Deploy triggered: ${deployId ?? deployStatus}`);
   987|
   988|          // ── PRODUCTION VERIFY ────────────────────────────────────────────
   989|          onPhase?.('production_verifying', 'Waiting for deploy + verifying production health.');
   990|          // Bounded wait for the deploy to propagate (simplified: poll health)
   991|          const sleep = input.sleepFn ?? ((ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms)));
   992|          await sleep(20_000);
   993|          const health = input.healthChecker
   994|            ? await input.healthChecker()
   995|            : await verifyProductionHealth();
   996|          healthOk = health.ok;
   997|          liveCommit = health.commit;
   998|          productionVerified = healthOk && liveCommit === commitSha;
   999|          if (productionVerified) {
  1000|            finalStatus = 'COMPLETED';
  1001|          } else {
  1002|            finalStatus = 'COMPLETED';
  1003|            error = `Deploy triggered but production verification inconclusive: healthOk=${healthOk}, liveCommit=${liveCommit}, expected=${commitSha}`;
  1004|          }
  1005|        } catch (err) {
