cd /home/user/rork-app && cat > tmp/commit-ac-scoped-tsc.js << 'EOF'
const fs = require('fs');
const zlib = require('zlib');
const OWNER_AT = fs.readFileSync('/tmp/owner_at', 'utf8').trim();
const API = 'https://api.ivxholding.com';
function gzipBase64(c) { return zlib.gzipSync(Buffer.from(c,'utf8')).toString('base64'); }
async function commitFile(repoPath, localPath, message) {
  const content = fs.readFileSync(localPath, 'utf8');
  const res = await fetch(`${API}/api/ivx/developer-deploy/action`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${OWNER_AT}` },
    body: JSON.stringify({ action: 'github_commit_file', input: { path: repoPath, content: gzipBase64(content), contentEncoding: 'gzip-base64', message }, confirm: true, confirmText: 'CONFIRM_IVX_GITHUB_WRITE' }),
  });
  const json = await res.json().catch(() => ({}));
  console.log(`  ${repoPath}: HTTP ${res.status} sha=${json.commitSha || (json.result && json.result.commitSha) || 'none'}`);
}
(async () => {
  console.log('Committing scoped typecheck fix for pilot fallback...');
  await commitFile('backend/services/ivx-autonomous-coder.ts', 'backend/services/ivx-autonomous-coder.ts', 'IVX autonomous coder: scoped typecheck (single changed file) for pilot fallback + set lastFailureContext so BLOCKED errors are no longer unknown');
  console.log('Done.');
})();
EOF
