import fs from 'node:fs';
const OWNER_AT = fs.readFileSync('/tmp/owner_at', 'utf8').trim();
const API = 'https://api.ivxholding.com';
const runId = `pilot5-${Date.now()}`;

const res = await fetch(`${API}/api/ivx/owner-ai`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${OWNER_AT}` },
  body: JSON.stringify({
    message: `Autonomous coder (run ${runId}): change the visible version label in the IVX owner dashboard from AUTONOMOUS-CODER-PILOT-1 to AUTONOMOUS-CODER-PILOT-2. Run targeted tests, typecheck, create a commit, but do not deploy.`,
  }),
});
const text = await res.text();
let json;
try { json = JSON.parse(text); } catch { json = { raw: text.slice(0, 500) }; }
console.log('HTTP', res.status);
const es = json.executionStatus || (json.result && json.result.executionStatus);
if (es) {
  console.log('executionStatus.taskId:', es.taskId);
  console.log('executionStatus.status:', es.status);
  console.log('executionStatus.stage:', es.stage);
  console.log('executionStatus.category:', es.category);
  console.log('executionStatus.httpStatus:', es.httpStatus);
  console.log('executionStatus.statusUrl:', es.statusUrl);
} else {
  console.log('executionStatus: ABSENT');
}
console.log('answer (first 1500):', (json.answer || json.text || '').slice(0, 1500));
if (es && es.taskId) {
  fs.writeFileSync('/tmp/pilot5_taskid.txt', es.taskId);
  console.log('taskId saved to /tmp/pilot5_taskid.txt');
}

